appsmith.onReady(function () {
  function getModel() {
    return appsmith.model || {};
  }
  function getInitial(value) {
    var text = String(value || '').trim();
    if (!text) {
      return 'U';
    }
    return text.charAt(0).toUpperCase();
  }
  function getActiveTab() {
    return getModel().activeTab || 'constructor';
  }
  function setActiveTabVisual(tabId) {
    var tabs = document.querySelectorAll('.workspace-tab');
    tabs.forEach(function (tab) {
      var isActive = tab.getAttribute('data-tab') === tabId;
      tab.classList.toggle('active', isActive);
      tab.setAttribute('aria-selected', isActive ? 'true' : 'false');
    });
  }
  function syncUser() {
    var model = getModel();
    var email = model.userEmail || '';
    var role = model.userRole || '';
    var emailElement = document.getElementById('workspaceUserEmail');
    var roleElement = document.getElementById('workspaceUserRole');
    var avatarElement = document.getElementById('workspaceUserAvatar');
    if (emailElement) {
      emailElement.textContent = email || 'Usuario';
    }
    if (roleElement) {
      roleElement.textContent = role || 'Sin rol';
    }
    if (avatarElement) {
      avatarElement.textContent = getInitial(email);
    }
  }
  function syncActiveQuery() {
    var model = getModel();
    var queryName = String(model.activeQueryName || '').trim();
    var queryId = String(model.activeQueryId || '').trim();
    var nameElement = document.getElementById('activeQueryName');
    var statusElement = document.querySelector('.context-status');
    if (nameElement) {
      nameElement.textContent = queryName || 'Seleccionar consulta';
    }
    if (statusElement) {
      statusElement.style.opacity = queryId ? '1' : '0.35';
    }
  }
  function syncShell() {
    syncUser();
    syncActiveQuery();
    setActiveTabVisual(getActiveTab());
  }
  async function changeTab(tabId) {
    if (!tabId) {
      return;
    }
    if (tabId === getActiveTab()) {
      setActiveTabVisual(tabId);
      return;
    }
    setActiveTabVisual(tabId);
    try {
      await appsmith.updateModel({
        activeTab: tabId
      });
    } catch (error) {
      console.error('No fue posible cambiar la pestaña:', error);
      setActiveTabVisual(getActiveTab());
    }
  }
  function bindTabs() {
    var tabs = document.querySelectorAll('.workspace-tab');
    tabs.forEach(function (tab) {
      tab.setAttribute('role', 'tab');
      tab.addEventListener('click', function () {
        changeTab(tab.getAttribute('data-tab'));
      });
    });
  }
  bindTabs();
  syncShell();
  if (typeof appsmith.onModelChange === 'function') {
    appsmith.onModelChange(function () {
      syncShell();
    });
  }
});

