  height: 10px;
}

.bar-2 {
  height: 18px;
}

.bar-3 {
  height: 27px;
}

.bar-4 {
  height: 18px;
}

.bar-5 {
  height: 10px;
}

.brand-copy {
  display: flex;
  flex-direction: column;

  min-width: 0;
}

.brand-copy strong {
  color: #FFFFFF;

  font-family:
    "Playfair Display",
    serif;

  font-size: 15px;
  font-weight: 700;

  line-height: 1.15;

  white-space: nowrap;
}

.brand-copy span {
  margin-top: 3px;

  color:
    rgba(255, 255, 255, 0.47);

  font-size: 8px;
  font-weight: 600;

  letter-spacing: 0.14em;

  text-transform: uppercase;

  white-space: nowrap;
}

/* =========================================================
   TOOLBAR
   ========================================================= */

.workspace-tools {
  flex: 1;

  min-width: 0;

  display: flex;
  justify-content: flex-end;
  align-items: center;

  gap: 8px;

  position: relative;
  z-index: 2;
}

/* =========================================================
   SEARCH
   ========================================================= */

.workspace-search {
  flex: 1;

  max-width: 410px;
  min-width: 190px;

  height: 42px;

  display: flex;
  align-items: center;

  gap: 9px;

  padding: 0 13px;

  border-radius: 12px;

  background:
    rgba(255, 255, 255, 0.08);

  border:
    1px solid
    rgba(255, 255, 255, 0.12);

  backdrop-filter:
    blur(10px);

  transition:
    border-color 0.2s,
    background 0.2s,
    box-shadow 0.2s;
}

.workspace-search:focus-within {
  background:
    rgba(255, 255, 255, 0.12);

  border-color:
    rgba(46, 155, 203, 0.75);

  box-shadow:
    0 0 0 3px
    rgba(46, 155, 203, 0.12);
}

.search-icon {
  width: 15px;
  height: 15px;

  position: relative;

  flex-shrink: 0;
}

.search-icon::before {
  content: "";

  position: absolute;

  width: 8px;
  height: 8px;

  border:
    1.7px solid
    rgba(255, 255, 255, 0.65);

  border-radius: 50%;

  left: 0;
  top: 0;
}

.search-icon::after {
  content: "";

  position: absolute;

  width: 6px;
  height: 1.7px;

  background:
    rgba(255, 255, 255, 0.65);

  transform:
    rotate(45deg);

  left: 9px;
  top: 10px;

  border-radius: 2px;
}

.workspace-search input {
  width: 100%;

  border: none;
  outline: none;

  background: transparent;

  color: #FFFFFF;

  font-family:
    "DM Sans",
    sans-serif;

  font-size: 11px;
}

.workspace-search input::placeholder {
  color:
    rgba(255, 255, 255, 0.42);
}

/* =========================================================
   CONTEXTO / CONSULTA ACTIVA
   ========================================================= */

.context-selector {
  height: 42px;

  min-width: 180px;
  max-width: 225px;

  display: flex;
  align-items: center;

  gap: 9px;

  padding: 0 12px;

  border-radius: 12px;

  border:
    1px solid
    rgba(255, 255, 255, 0.12);

  background:
    rgba(255, 255, 255, 0.08);

  color: #FFFFFF;

  font-family:
    "DM Sans",
    sans-serif;

  cursor: pointer;

  transition:
    background 0.2s,
    border-color 0.2s;
}

.context-selector:hover {
  background:
    rgba(255, 255, 255, 0.12);

  border-color:
    rgba(46, 155, 203, 0.62);
}

.context-status {
  width: 8px;
  height: 8px;

  border-radius: 50%;

  background: #47D7A0;

  box-shadow:
    0 0 0 4px
    rgba(71, 215, 160, 0.12);

  flex-shrink: 0;
}

.context-copy {
  min-width: 0;

  flex: 1;

  display: flex;
  flex-direction: column;

  align-items: flex-start;
}

.context-copy small {
  color:
    rgba(255, 255, 255, 0.43);

  font-size: 7px;

  line-height: 1.2;

  text-transform: uppercase;

  letter-spacing: 0.1em;
}

.context-copy strong {
  width: 100%;

  margin-top: 2px;

  overflow: hidden;

  color: #FFFFFF;

  font-size: 10px;
  font-weight: 600;

  text-align: left;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.context-chevron,
.user-chevron {
  width: 7px;
  height: 7px;

  border-right:
    1.5px solid
    rgba(255, 255, 255, 0.55);

  border-bottom:
    1.5px solid
    rgba(255, 255, 255, 0.55);

  transform:
    rotate(45deg)
    translateY(-2px);

  flex-shrink: 0;
}

/* =========================================================
   NOTIFICACIONES
   ========================================================= */

.header-icon-button {
  width: 42px;
  height: 42px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 12px;

  border:
    1px solid
    rgba(255, 255, 255, 0.12);

  background:
    rgba(255, 255, 255, 0.08);

  cursor: pointer;

  transition:
    background 0.2s,
    border-color 0.2s;
}

.header-icon-button:hover {
  background:
    rgba(255, 255, 255, 0.12);

  border-color:
    rgba(46, 155, 203, 0.62);
}

.notification-icon {
  width: 15px;
  height: 16px;

  position: relative;
}

.notification-icon::before {
  content: "";

  position: absolute;

  width: 10px;
  height: 11px;

  left: 2px;
  top: 0;

  border:
    1.5px solid
    rgba(255, 255, 255, 0.75);

  border-radius:
    7px 7px 4px 4px;
}

.notification-icon::after {
  content: "";

  position: absolute;

  width: 4px;
  height: 2px;

  left: 5px;
  bottom: 0;

  border-radius:
    0 0 4px 4px;

  background:
    rgba(255, 255, 255, 0.75);
}

/* =========================================================
   USUARIO
   ========================================================= */

.workspace-user {
  height: 42px;

  min-width: 150px;
  max-width: 200px;

  display: flex;
  align-items: center;

  gap: 9px;

  padding: 0 10px;

  border-radius: 12px;

  border:
    1px solid
    rgba(255, 255, 255, 0.12);

  background:
    rgba(255, 255, 255, 0.08);

  font-family:
    "DM Sans",
    sans-serif;

  cursor: pointer;

  transition:
    background 0.2s,
    border-color 0.2s;
}

.workspace-user:hover {
  background:
    rgba(255, 255, 255, 0.12);

  border-color:
    rgba(46, 155, 203, 0.62);
}

.workspace-user-avatar {
  width: 28px;
  height: 28px;

  border-radius: 9px;

  display: flex;
  align-items: center;
  justify-content: center;

  flex-shrink: 0;

  background:
    linear-gradient(
      145deg,
      #2E9BCB,
      #2972A9
    );

  color: #FFFFFF;

  font-size: 10px;
  font-weight: 700;

  box-shadow:
    0 5px 14px
    rgba(46, 155, 203, 0.22);
}

.workspace-user-copy {
  min-width: 0;

  flex: 1;

  display: flex;
  flex-direction: column;

  align-items: flex-start;
}

.workspace-user-copy strong {
  width: 100%;

  overflow: hidden;

  color: #FFFFFF;

  font-size: 9px;
  font-weight: 600;

  text-align: left;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.workspace-user-copy small {
  margin-top: 1px;

  color:
    rgba(255, 255, 255, 0.42);

  font-size: 7px;

  text-transform: uppercase;

  letter-spacing: 0.08em;
}

/* =========================================================
   NAVEGACIÓN POR PESTAÑAS
   ========================================================= */

.workspace-tabs {
  min-height: 66px;

  display: grid;

  grid-template-columns:
    repeat(
      7,
      minmax(0, 1fr)
    );

  gap: 5px;

  padding: 6px;

  margin-top: 5px;

  border-radius:
    10px 10px 18px 18px;

  border:
    1px solid var(--line);

  background:
    rgba(255, 255, 255, 0.92);

  box-shadow:
    0 10px 24px
    rgba(47, 50, 59, 0.07);

  backdrop-filter:
    blur(16px);
}

.workspace-tab {
  position: relative;

  min-width: 0;
  min-height: 52px;

  display: flex;
  align-items: center;

  gap: 9px;

  padding:
    7px 10px;

  border: none;

  border-radius: 12px;

  background: transparent;

  color: var(--muted);

  font-family:
    "DM Sans",
    sans-serif;

  cursor: pointer;

  overflow: hidden;

  transition:
    background 0.2s,
    color 0.2s,
    box-shadow 0.2s,
    transform 0.2s;
}

.workspace-tab:hover {
  color: var(--blue);

  background:
    rgba(167, 205, 222, 0.15);
}

.workspace-tab.active {
  color: #FFFFFF;

  background:
    linear-gradient(
      135deg,
      #2972A9,
      #2E9BCB
    );

  box-shadow:
    0 7px 18px
    rgba(41, 114, 169, 0.22);

  transform:
    translateY(-1px);
}

.workspace-tab.active::after {
  content: "";

  position: absolute;

  width: 70px;
  height: 70px;

  right: -25px;
  top: -35px;

  border-radius: 50%;

  background:
    rgba(255, 255, 255, 0.10);
}

.tab-copy {
  min-width: 0;

  display: flex;
  flex-direction: column;

  align-items: flex-start;

  position: relative;
  z-index: 2;
}

.tab-copy strong {
  width: 100%;

  overflow: hidden;

  font-size: 10px;
  font-weight: 700;

  text-align: left;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.tab-copy small {
  width: 100%;

  margin-top: 2px;

  overflow: hidden;

  color: #8C929A;

  font-size: 7px;
  font-weight: 500;

  text-align: left;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.workspace-tab.active .tab-copy small {
  color:
    rgba(255, 255, 255, 0.70);
}

/* =========================================================
   ICONOS PESTAÑAS
   ========================================================= */

.tab-icon {
  width: 27px;
  height: 27px;

  border-radius: 9px;

  flex-shrink: 0;

  display: flex;
  align-items: center;
  justify-content: center;

  position: relative;
  z-index: 2;

  background:
    rgba(41, 114, 169, 0.08);

  color: var(--blue);
}

.workspace-tab.active .tab-icon {
  background:
    rgba(255, 255, 255, 0.17);

  color: #FFFFFF;
}

/* constructor */

.tab-icon-constructor::before {
  content: "";

  width: 12px;
  height: 12px;

  border:
    1.6px solid
    currentColor;

  border-radius: 3px;

  box-shadow:
    4px 4px 0 -2px
    currentColor;
}

/* live */

.tab-icon-live::before {
  content: "";

  width: 7px;
  height: 7px;

  border-radius: 50%;

  background: currentColor;

  box-shadow:
    0 0 0 4px
    rgba(46, 155, 203, 0.12);
}

.workspace-tab.active
.tab-icon-live::before {
  box-shadow:
    0 0 0 4px
    rgba(255, 255, 255, 0.15);
}

/* mentions */

.tab-icon-mentions::before {
  content: "";

  width: 13px;
  height: 10px;

  border:
    1.6px solid
    currentColor;

  border-radius: 5px;
}

.tab-icon-mentions::after {
  content: "";

  position: absolute;

  width: 5px;
  height: 5px;

  left: 7px;
  bottom: 5px;

  border-left:
    1.6px solid
    currentColor;

  border-bottom:
    1.6px solid
    currentColor;

  transform:
    skew(-25deg);
}

/* actors */

.tab-icon-actors::before {
  content: "";

  position: absolute;

  width: 6px;
  height: 6px;

  border-radius: 50%;

  border:
    1.5px solid
    currentColor;

  top: 5px;
  left: 10px;
}

.tab-icon-actors::after {
  content: "";

  position: absolute;

  width: 13px;
  height: 7px;

  border:
    1.5px solid
    currentColor;

  border-bottom: none;

  border-radius:
    9px 9px 0 0;

  left: 6px;
  bottom: 5px;
}

/* sentiment */

.tab-icon-sentiment::before {
  content: "";

  width: 14px;
  height: 14px;

  border:
    1.5px solid
    currentColor;

  border-radius: 50%;
}

.tab-icon-sentiment::after {
  content: "⌣";

  position: absolute;

  left: 7px;
  top: 3px;

  font-size: 13px;
  line-height: 16px;

  color: currentColor;
}

/* alerts */

.tab-icon-alerts::before {
  content: "";

  width: 11px;
  height: 12px;

  border:
    1.5px solid
    currentColor;

  border-radius:
    7px 7px 4px 4px;
}

.tab-icon-alerts::after {
  content: "";

  position: absolute;

  width: 4px;
  height: 2px;

  bottom: 4px;

  border-radius:
    0 0 4px 4px;

  background:
    currentColor;
}

/* reports */

.tab-icon-reports::before {
  content: "";

  width: 11px;
  height: 14px;

  border:
    1.5px solid
    currentColor;

  border-radius: 2px;
}

.tab-icon-reports::after {
  content: "";

  position: absolute;

  width: 6px;
  height: 1px;

  background:
    currentColor;

  box-shadow:
    0 4px 0
    currentColor;
}

/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1120px) {
  .workspace-search {
    max-width: 290px;
  }

  .context-selector {
    min-width: 155px;
  }

  .workspace-user {
    min-width: 125px;
  }

  .tab-copy small {
    display: none;
  }

  .workspace-tab {
    justify-content: center;
  }
}

@media (max-width: 900px) {
  .workspace-brand {
    min-width: auto;
  }

  .brand-copy span {
    display: none;
  }

  .workspace-search {
    display: none;
  }

  .workspace-user-copy {
    display: none;
  }

  .workspace-user {
    min-width: 42px;
    width: 42px;

    padding: 0;

    justify-content: center;
  }

  .workspace-user .user-chevron {
    display: none;
  }

  .workspace-tabs {
    overflow-x: auto;

    grid-template-columns:
      repeat(7, 130px);
  }
}

